function smartAppDate(row){const serial=num(row['Date (extracted)']);return serial===null?day(row.Date):new Date(1899,11,30+serial)}
function smartAppInputDate(date){if(!date)return'';return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function excludedSmartAppTitle(title){const value=String(title||'').toLowerCase();return['course project','catch up class','trial class','pre class','complementary class','holiday class'].some(term=>value.includes(term))}
function makeSmartAppRows(raw){return raw.map(row=>{const date=smartAppDate(row),branch=String(row.Branch||'').trim(),title=String(row['Session Title']||'').trim(),week=String(row.Week||'').trim(),group=String(row['Cohort Group Serial']||row.Cohort||'').trim();return{serial:String(row['Session Serial']||'').trim(),branch,title,date,dateLabel:String(row.Date||smartAppInputDate(date)).trim(),week,weekKey:date&&week?`${date.getFullYear()}|${week}`:'',classKey:group||title.toLowerCase(),connected:num(row['Session Has Activity Score'])===1,program:String(row.Program||'').trim(),level:String(row.Level||'').trim(),teacher:String(row['Teacher Name']||'').trim(),backfilled:num(row.Backfilled)??0,check:String(row.Check||'').trim().toLowerCase()}}).filter(row=>row.branch&&row.title&&!excludedSmartAppTitle(row.title)&&row.date&&row.weekKey&&row.classKey&&(!row.check||row.check==='unique'))}
function smartAppWeeks(){return[...new Map(smartAppRows.map(row=>[row.weekKey,row.date])).entries()].sort((a,b)=>a[1]-b[1]).map(([key])=>key)}
function selectedSmartAppRows(){const start=day(smartAppState.start),end=day(smartAppState.end);return smartAppRows.filter(row=>{const inDate=smartAppState.mode==='week'?row.weekKey===smartAppState.week:(!start||row.date>=start)&&(!end||row.date<=end),isWaveOneToFive=waveOneToFive.has(branchKey(row.branch));return inDate&&(smartAppState.wave==='all'||(smartAppState.wave==='wave1to5'?isWaveOneToFive:!isWaveOneToFive))})}
function aggregateSmartApp(rows){const branches=new Map;rows.forEach(row=>{const branch=branches.get(row.branch)||new Map,key=`${row.weekKey}|${row.classKey}`,item=branch.get(key)||{connected:false};item.connected||=row.connected;branch.set(key,item);branches.set(row.branch,branch)});return[...branches].map(([branch,classes])=>{const scheduled=classes.size,connected=[...classes.values()].filter(item=>item.connected).length;return{branch,scheduled,connected,pct:scheduled?connected/scheduled*100:0}})}
function smartUsageColor(pct){return pct<25?'#b3261e':pct<50?'#df6b63':pct<75?'#69a84f':'#1fa32d'}
function smartAppTitle(){const title=document.querySelector('#academic .page-title'),link=document.getElementById('academicLink');if(!title)return;title.querySelector('.eyebrow').textContent='ACADEMIC PERFORMANCE';title.querySelector('h1').innerHTML='SmartApp <em>Usage.</em>';title.querySelector('div>p:not(.eyebrow)').textContent='Weekly SmartApp usage by unique class across Indonesia Timur branches.';if(link){link.href='https://docs.google.com/spreadsheets/d/1XseG7ElM_WrGrE8TAeWffGQ3J_Iigl9XaizAlEyHO9k/edit?gid=1642365570#gid=1642365570';link.textContent='Open source ↗'}}
function renderSmartAppOverall(){const panel=document.getElementById('smartAppPanel');if(!panel)return;let rows=aggregateSmartApp(selectedSmartAppRows());rows.sort((a,b)=>smartAppState.sort==='high'?b.pct-a.pct||a.branch.localeCompare(b.branch):smartAppState.sort==='low'?a.pct-b.pct||a.branch.localeCompare(b.branch):a.branch.localeCompare(b.branch));const scheduled=rows.reduce((sum,row)=>sum+row.scheduled,0),connected=rows.reduce((sum,row)=>sum+row.connected,0),pct=scheduled?connected/scheduled*100:0,weeks=smartAppWeeks();panel.innerHTML=`<section class="smart-header"><p class="eyebrow">SMARTAPP PERFORMANCE</p><h2>Overall Usage</h2><p>Each class is counted once per week. A class counts as connected when at least one scheduled session has an activity score.</p></section><div class="smart-view-tabs filter-switch" role="group" aria-label="SmartApp view"><button class="active" data-smart-view="overall">Overall Usage</button><button data-smart-view="details">Details</button></div><div class="smart-controls"><div class="filter-switch" role="group" aria-label="SmartApp date filter"><button class="${smartAppState.mode==='week'?'active':''}" data-smart-mode="week">Filter by week</button><button class="${smartAppState.mode==='period'?'active':''}" data-smart-mode="period">Filter by period</button></div><select id="smartWeek" ${smartAppState.mode==='week'?'':'hidden'} aria-label="Select SmartApp week">${weeks.map(week=>`<option value="${esc(week)}" ${week===smartAppState.week?'selected':''}>${esc(weekLabel(week))}</option>`).join('')}</select><div class="smart-period" ${smartAppState.mode==='period'?'':'hidden'}><label>From <input id="smartStart" type="date" value="${esc(smartAppState.start)}"></label><label>To <input id="smartEnd" type="date" value="${esc(smartAppState.end)}"></label><button id="applySmartPeriod" class="control-button">Apply</button></div><select id="smartWave" aria-label="Filter SmartApp branches by wave"><option value="all">All branches</option><option value="wave1to5" ${smartAppState.wave==='wave1to5'?'selected':''}>Wave 1–5</option><option value="wave6" ${smartAppState.wave==='wave6'?'selected':''}>Wave 6</option></select><select id="smartSort" aria-label="Sort SmartApp usage"><option value="name">A–Z</option><option value="high" ${smartAppState.sort==='high'?'selected':''}>Usage: high to low</option><option value="low" ${smartAppState.sort==='low'?'selected':''}>Usage: low to high</option></select></div><div class="smart-summary"><div><span>Interactive sessions scheduled</span><strong>${scheduled}</strong></div><div><span>Sessions connected to TV</span><strong>${connected}</strong></div><div><span>Usage rate · Target ≥80%</span><strong style="color:${smartUsageColor(pct)}">${pct.toFixed(1)}%</strong></div></div><div class="data-shell smart-table-shell"><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Interactive Session Scheduled<br>(Unique class)</th><th>Session Connect TV<br>(Unique class)</th><th>% Session Connect<br>to TV</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.branch)}</strong></td><td>${row.scheduled}</td><td>${row.connected}</td><td><div class="smart-usage"><strong style="color:${smartUsageColor(row.pct)}">${row.pct.toFixed(1)}%</strong><span><i style="width:${row.pct.toFixed(1)}%;background:${smartUsageColor(row.pct)}"></i></span></div></td></tr>`).join('')||'<tr><td colspan="4">No SmartApp sessions found for this filter.</td></tr>'}</tbody></table></div></div><p class="smart-note">“Session Connect TV” follows Column G (Session Has Activity Score), as specified.</p>`;panel.querySelectorAll('[data-smart-view]').forEach(button=>button.addEventListener('click',()=>setSmartAppView(button.dataset.smartView)));panel.querySelectorAll('[data-smart-mode]').forEach(button=>button.addEventListener('click',()=>{smartAppState.mode=button.dataset.smartMode;renderSmartApp()}));panel.querySelector('#smartWeek')?.addEventListener('change',event=>{smartAppState.week=event.target.value;renderSmartApp()});panel.querySelector('#smartWave')?.addEventListener('change',event=>{smartAppState.wave=event.target.value;renderSmartApp()});panel.querySelector('#smartSort')?.addEventListener('change',event=>{smartAppState.sort=event.target.value;renderSmartApp()});panel.querySelector('#applySmartPeriod')?.addEventListener('click',()=>{smartAppState.start=panel.querySelector('#smartStart').value;smartAppState.end=panel.querySelector('#smartEnd').value;renderSmartApp()})}
function setSmartAppView(view){smartAppState.view=view==='details'?'details':'overall';localStorage.setItem('acops-smartapp-view',smartAppState.view);syncAcademicDock(2,`SmartApp Usage · ${smartAppState.view==='details'?'Details':'Overall Usage'}`);renderSmartApp()}
