function mppBranchRows(){const branches=new Map;activeCenterNames.forEach((branch,key)=>{const groupKey=dashboardCenterGroupKey(branch),entry=branches.get(groupKey)||{groupKey,branch,coach:0,mitra:0};entry.branch=mppDisplayBranch(groupKey,entry.branch);branches.set(groupKey,entry)});const seen=new Set;mppRoster.forEach(row=>{const groupKey=dashboardCenterGroupKey(row.branch),identity=`${groupKey}|${row.type}|${row.email.toLowerCase()||row.teacher.toLowerCase()}`;if(seen.has(identity))return;seen.add(identity);const entry=branches.get(groupKey)||{groupKey,branch:mppDisplayBranch(groupKey,row.branch),coach:0,mitra:0};entry.branch=mppDisplayBranch(groupKey,entry.branch);entry[row.type]++;branches.set(groupKey,entry)});return[...branches.values()].filter(row=>mppWaveMatch(row.groupKey,row.branch)).sort((a,b)=>a.branch.localeCompare(b.branch))}
function initMppWaveFilter(){const select=document.getElementById('mppWave');if(!select||select.dataset.bound)return;select.dataset.bound='true';select.value=mppState.wave;select.addEventListener('change',async event=>{mppState.wave=event.target.value;if(mppState.wave!=='all'&&!activeCenterBranches.size)try{await loadWaveBranches()}catch(error){console.warn('MPP branch wave source unavailable',error)}renderMppNeeds()})}
