const mppEditAccessCode='240425',mppEditSessionKey='acops-mpp-edit-unlocked',mppEditAttemptsKey='acops-mpp-edit-attempts',mppEditLockKey='acops-mpp-edit-lock-until';
function mppEditingUnlocked(){return sessionStorage.getItem(mppEditSessionKey)==='true'}
function applyMppEditAccess(){const unlocked=mppEditingUnlocked(),button=document.getElementById('mppEditToggle'),hiringButton=document.getElementById('hiringEditToggle');document.querySelectorAll('[data-mpp-branch],.mpp-priority-trigger').forEach(control=>{control.disabled=!unlocked});document.getElementById('mppNeedsTable')?.classList.toggle('editing-unlocked',unlocked);[button,hiringButton].forEach(control=>{if(!control)return;control.classList.toggle('active',unlocked);control.textContent=unlocked?'✓':'✎';control.setAttribute('aria-label',unlocked?'Lock editing':'Unlock editing');control.title=unlocked?'Lock editing':'Unlock editing'})}
function mppLockRemaining(){return Math.max(0,Number(localStorage.getItem(mppEditLockKey)||0)-Date.now())}
function openMppEditDialog(){const remaining=mppLockRemaining(),dialog=document.getElementById('mppEditDialog'),message=document.getElementById('mppEditMessage'),input=document.getElementById('mppEditCode');if(remaining){const minutes=Math.ceil(remaining/60000);window.alert(`Too many incorrect attempts. Try again in ${minutes} minute${minutes===1?'':'s'}.`);return}localStorage.removeItem(mppEditLockKey);message.textContent='';input.value='';dialog.showModal();setTimeout(()=>input.focus(),0)}
function initMppEditLock(){const button=document.getElementById('mppEditToggle'),form=document.getElementById('mppEditForm'),dialog=document.getElementById('mppEditDialog'),closeButton=dialog?.querySelector('.mpp-dialog-close');if(!button||button.dataset.bound)return;button.dataset.bound='true';if(closeButton){closeButton.type='button';closeButton.addEventListener('click',()=>dialog.close('cancel'))}dialog?.addEventListener('close',()=>{document.getElementById('mppEditCode').value='';document.getElementById('mppEditMessage').textContent=''});button.addEventListener('click',()=>{if(mppEditingUnlocked()){sessionStorage.removeItem(mppEditSessionKey);applyMppEditAccess();if(!document.getElementById('hiringPanel')?.hidden&&hiringLoaded)renderHiring();setMppSaveStatus('Editing locked','local')}else openMppEditDialog()});form.addEventListener('submit',event=>{event.preventDefault();const input=document.getElementById('mppEditCode'),message=document.getElementById('mppEditMessage');if(input.value===mppEditAccessCode){sessionStorage.setItem(mppEditSessionKey,'true');localStorage.removeItem(mppEditAttemptsKey);localStorage.removeItem(mppEditLockKey);dialog.close();applyMppEditAccess();if(!document.getElementById('hiringPanel')?.hidden&&hiringLoaded)renderHiring();setMppSaveStatus('Editing unlocked','synced');return}const attempts=Number(localStorage.getItem(mppEditAttemptsKey)||0)+1,remaining=3-attempts;if(attempts>=3){localStorage.setItem(mppEditAttemptsKey,'0');localStorage.setItem(mppEditLockKey,String(Date.now()+15*60*1000));dialog.close();window.alert('Too many incorrect attempts. Editing is locked for 15 minutes.')}else{localStorage.setItem(mppEditAttemptsKey,String(attempts));message.textContent=`Incorrect code. ${remaining} attempt${remaining===1?'':'s'} remaining.`;input.value='';input.focus()}});applyMppEditAccess()}
