function renderMppOverview(rows,label){const root=document.getElementById('mppOverview');if(!root)return;const section=(code,title)=>{const matches=rows.filter(row=>row.priority.code===code).sort((a,b)=>b.gap-a.gap||a.branch.localeCompare(b.branch));return`<section class="${code.toLowerCase()}"><div><h4>${code} · ${title}</h4><span>${matches.length} branches</span></div>${matches.length?`<ol>${matches.map(row=>`<li><span>${esc(row.branch)}</span><strong>${row.gap>0?'+':''}${row.gap}</strong></li>`).join('')}</ol>`:'<p>No branches in this priority.</p>'}</section>`};root.innerHTML=`<p class="eyebrow">HIRING OVERVIEW</p><h3>${esc(label)} priorities</h3><p class="mpp-overview-copy">Branches currently marked P0 or P1 and their staffing gap.</p>${section('P0','Urgent')}${section('P1','Attention')}`}
function renderMppNeedsContent(){const label=mppState.view==='coach'?'MT Coach':'MT Mitra',priorityLabel={P0:'Urgent',P1:'Attention',P2:'Covered'},rows=mppBranchRows().map(row=>{const existing=row[mppState.view],key=mppNeedKey(mppState.view,row.branch),stored=mppNeeds[key],needs=Number.isFinite(Number(stored))?Math.max(0,Number(stored)):0,gap=needs-existing,code=mppPriorities[key]||mppPriority(gap).code,priority={code,label:priorityLabel[code]};return{...row,existing,needs,gap,priority}}),totalExisting=rows.reduce((sum,row)=>sum+row.existing,0),totalNeeds=rows.reduce((sum,row)=>sum+row.needs,0),shortage=rows.reduce((sum,row)=>sum+Math.max(0,row.gap),0),urgent=rows.filter(row=>row.priority.code==='P0').length;document.querySelectorAll('[data-mpp-view]').forEach(button=>button.classList.toggle('active',button.dataset.mppView===mppState.view));document.getElementById('mppTableTitle').textContent=`${label} staffing needs`;document.getElementById('mppBranchCount').textContent=`${rows.length} branches`;document.getElementById('mppSummary').innerHTML=`<div><span>Existing ${esc(label)}</span><strong>${totalExisting}</strong></div><div><span>Total needed</span><strong>${totalNeeds}</strong></div><div><span>Open gap</span><strong>${shortage}</strong></div><div class="${urgent?'urgent':''}"><span>P0 branches</span><strong>${urgent}</strong></div>`;document.getElementById('mppNeedsTable').innerHTML=`<table><thead><tr><th>Branch</th><th>Total ${esc(label)}</th><th>${esc(label)} Needs</th><th>Gap</th><th>Priority</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.branch)}</strong></td><td>${row.existing}</td><td><label class="mpp-needs-input"><input type="number" min="0" step="1" value="${row.needs}" data-mpp-branch="${esc(row.branch)}" aria-label="${esc(label)} needs for ${esc(row.branch)}"/></label></td><td><strong class="mpp-gap ${row.gap>0?'shortage':row.gap<0?'surplus':''}">${row.gap>0?'+':''}${row.gap}</strong></td><td><label class="mpp-priority-select ${row.priority.code.toLowerCase()}"><select data-mpp-priority="${esc(row.branch)}" aria-label="Priority for ${esc(row.branch)}">${['P0','P1','P2'].map(code=>`<option value="${code}" ${code===row.priority.code?'selected':''}>${code} · ${priorityLabel[code]}</option>`).join('')}</select></label></td></tr>`).join('')||'<tr><td colspan="5">No active Master Teachers found.</td></tr>'}</tbody></table>`;document.querySelectorAll('[data-mpp-branch]').forEach(input=>input.addEventListener('change',async event=>{const branch=event.target.dataset.mppBranch,needs=Math.max(0,Math.round(Number(event.target.value)||0)),view=mppState.view;event.target.disabled=true;try{await saveMppNeed(view,branch,needs);renderMppNeeds()}catch(error){console.warn('Hiring PRIO save failed',error);setMppSaveStatus(`Couldn’t sync: ${error.message}`,'error');event.target.disabled=false}}));document.querySelectorAll('[data-mpp-priority]').forEach(select=>select.addEventListener('change',async event=>{const branch=event.target.dataset.mppPriority,priority=event.target.value,view=mppState.view;event.target.disabled=true;try{await saveMppPriority(view,branch,priority);renderMppNeeds()}catch(error){console.warn('Hiring PRIO priority save failed',error);setMppSaveStatus(`Couldn’t sync: ${error.message}`,'error');event.target.disabled=false}}))}
function enhanceMppNoNeedOptions(){const names={P0:'P0 · Urgent',P1:'P1 · Attention',FILLED:'Filled','NO NEED':'No Need'},styleClass={P0:'p0',P1:'p1',FILLED:'filled','NO NEED':'no-need'};document.querySelectorAll('[data-mpp-priority]').forEach(select=>{select.insertAdjacentHTML('beforeend','<option value="FILLED">Filled</option><option value="NO NEED">No Need</option>');const key=mppNeedKey(mppState.view,select.dataset.mppPriority),saved=mppPriorities[key],desired=saved==='P2'?'FILLED':saved||select.value,label=select.closest('.mpp-priority-select');if(saved==='P2')mppPriorities[key]='FILLED';select.value=desired;select.hidden=true;if(label){label.classList.remove('p0','p1','p2','filled','no-need','no','need');label.classList.add(styleClass[desired]||'filled')}label?.insertAdjacentHTML('beforeend',`<div class="mpp-priority-menu"><button type="button" class="mpp-priority-trigger" aria-haspopup="listbox" aria-expanded="false">${names[desired]}</button><div class="mpp-priority-options" role="listbox" hidden>${Object.entries(names).map(([value,name])=>`<button type="button" role="option" data-value="${value}" aria-selected="${value===desired}" class="${value===desired?'selected':''}"><span class="mpp-option-check">✓</span><span>${name}</span></button>`).join('')}</div></div>`);const trigger=label?.querySelector('.mpp-priority-trigger'),options=label?.querySelector('.mpp-priority-options');trigger?.addEventListener('click',event=>{event.stopPropagation();document.querySelectorAll('.mpp-priority-options').forEach(menu=>{if(menu!==options)menu.hidden=true});options.hidden=!options.hidden;trigger.setAttribute('aria-expanded',String(!options.hidden))});options?.querySelectorAll('[data-value]').forEach(button=>button.addEventListener('click',()=>{select.value=button.dataset.value;select.dispatchEvent(new Event('change',{bubbles:true}))}))});if(!document.body.dataset.mppPriorityClose){document.body.dataset.mppPriorityClose='true';document.addEventListener('click',()=>document.querySelectorAll('.mpp-priority-options').forEach(menu=>{menu.hidden=true}))}}
function renderMppNeeds(){renderMppNeedsContent();enhanceMppNoNeedOptions();const label=mppState.view==='coach'?'MT Coach':'MT Mitra',rows=mppBranchRows().map(row=>{const existing=row[mppState.view],key=mppNeedKey(mppState.view,row.branch),stored=mppNeeds[key],needs=Number.isFinite(Number(stored))?Math.max(0,Number(stored)):0,gap=needs-existing,code=mppPriorities[key]||mppPriority(gap).code;return{...row,existing,needs,gap,priority:{code}}});renderMppOverview(rows,label);document.querySelectorAll('.mpp-gap,.mpp-overview li strong').forEach(node=>{node.textContent=node.textContent.replace(/^\+/,'')});applyMppEditAccess()}
async function initMppNeeds(){document.getElementById('operationsLink').href=`https://docs.google.com/spreadsheets/d/${sources.operations.id}/edit?gid=${mppHiringGid}#gid=${mppHiringGid}`;if(!document.body.dataset.mppBound){document.body.dataset.mppBound='true';document.querySelectorAll('[data-mpp-view]').forEach(button=>button.addEventListener('click',()=>{mppState.view=button.dataset.mppView;renderMppNeeds()}));document.getElementById('mppConnectSheet')?.addEventListener('click',connectMppSheet)}updateMppConnectionButton();if(mppLoaded||mppLoading){if(mppLoaded)renderMppNeeds();return}mppLoading=true;try{mppRoster=await loadMppRoster();mppLoaded=true;renderMppNeeds();document.getElementById('lastUpdated')?.replaceChildren(document.createTextNode('Live MPP roster loaded'));try{await loadHiringPrioNeeds();renderMppNeeds();setMppSaveStatus(mppApiToken()?'Connected to Hiring PRIO':'Loaded from Hiring PRIO · connect to edit',mppApiToken()?'synced':'local')}catch(error){console.warn('Hiring PRIO values could not refresh; cached values were kept',error);setMppSaveStatus(mppApiToken()?'Connected · showing last saved values':'Showing last saved values','local')}}catch(error){console.warn('MPP roster could not load',error);if(mppRoster.length)renderMppNeeds();else document.getElementById('mppNeedsTable').innerHTML='<div class="empty-state"><strong>Couldn’t load the MPP roster.</strong><p>Check the All MPP source sharing settings, then refresh.</p></div>'}finally{mppLoading=false}}
const hiringSheetName='Hiring EA';
const hiringSteps=['Approached','Pre-screening','Online Test','Online Test New','Onsite Assessment','Interview','Onsite Wave 6','Offering Letter','Onboarding','Video Ajar','Ready to Teach','Onboarding Regional','Nego','Approval HQ','Reference Check','Rejected/Cancelled','Postponed','No Info'];
let hiringRows=[],hiringLoaded=false,hiringLoading=false,hiringSelected='',hiringState={search:'',role:'all',step:'all',center:''},hiringAddresses=new Map;
function hiringCell(row,index){const cell=row.c?.[index];return cell?(cell.f??cell.v??''):''}
function hiringPhone(value){let digits=String(value||'').replace(/\D/g,'');if(digits.startsWith('0'))digits=`62${digits.slice(1)}`;else if(digits.startsWith('8'))digits=`62${digits}`;return digits}
function hiringDateInput(value){const date=sheetDate(value);return date?localDateInput(date):''}
function hiringStepClass(value){if(!value)return'step-no-info';const slug=String(value).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');return slug?`step-${slug}`:'step-no-info'}
function hiringIdentity(row){return{name:row.name,email:row.email,phone:row.phone,center:row.center}}
async function loadHiringRows(){const query=encodeURIComponent('select A,B,C,D,E,H,I,J,K where C is not null'),response=await fetch(`${gvizUrl(sources.operations,hiringSheetName,0)}&tq=${query}&_=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw Error('Hiring EA unavailable');const table=parseGViz(await response.text()),seen=new Set;hiringAddresses=new Map;return table.rows.map((row,index)=>{const item={id:`cand-${index}-${Math.random().toString(36).slice(2,8)}`,address:hiringCell(row,0),center:hiringCell(row,1),name:hiringCell(row,2),email:hiringCell(row,3),phone:hiringCell(row,4),role:hiringCell(row,5),step:hiringCell(row,6),onsiteDate:hiringCell(row,7),notes:hiringCell(row,8)};if(item.center&&item.address)hiringAddresses.set(item.center,item.address);item.original=hiringIdentity(item);return item}).filter(row=>row.name&&row.name.toLowerCase()!=='nama'&&!seen.has(row.name.toLowerCase()+'|'+row.phone)&&(seen.add(row.name.toLowerCase()+'|'+row.phone),true))}
function hiringPassive(row){const step=String(row.step||'').toLowerCase();return step.includes('ready to teach')||step.includes('reject')||step.includes('cancel')}
function hiringStepRank(step){const index=hiringSteps.findIndex(item=>item.toLowerCase()===String(step||'').toLowerCase());return index<0?hiringSteps.length:index}
function hiringFilteredRows(){const term=hiringState.search.toLowerCase(),center=hiringState.center.toLowerCase();return hiringRows.filter(row=>{const haystack=[row.name,row.center,row.email,row.phone,row.role,row.step,row.notes].join(' ').toLowerCase();return(!term||haystack.includes(term))&&(hiringState.role==='all'||row.role===hiringState.role)&&(hiringState.step==='all'||row.step===hiringState.step)&&(!center||String(row.center||'').toLowerCase().includes(center))}).sort((a,b)=>{if(a.isNew||b.isNew){if(a.isNew&&b.isNew)return(b.addedAt||0)-(a.addedAt||0);return a.isNew?-1:1}return Number(hiringPassive(a))-Number(hiringPassive(b))||hiringStepRank(a.step)-hiringStepRank(b.step)||a.center.localeCompare(b.center)||a.name.localeCompare(b.name)})}
function fillHiringFilter(id,field,label){const select=document.getElementById(id);let values=[...new Set(hiringRows.map(row=>row[field]).filter(Boolean))];if(field==='step')values=[...new Set([...hiringSteps,...values])].sort((a,b)=>hiringStepRank(a)-hiringStepRank(b)||a.localeCompare(b));else values.sort((a,b)=>a.localeCompare(b));select.innerHTML=`<option value="all">All ${label}</option>${values.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('')}`;renderCustomSelect(select)}
function hiringMessage(row){const name=row.name||'Kak',center=row.center||'',location=row.address||hiringAddresses.get(row.center)||'',step=row.step||'';const onsite=`Hi *${name}*, this is Agnes from English Academy Center *${center}* 👋\n\nWe would like to invite you to ${step==='Onsite Wave 6'?'a demo teaching session':'an interview and demo teaching session'} as part of our recruitment process.\n\nDetails:\n- Date:\n- Time:\n- Location: ${location}\n\nPlease prepare a 10–15 minute lesson on the topic 'Transportation' for students aged 10–12. You will teach in front of the panel acting as students.\n\nGuidelines:\n- Warm-up (2–3 min): short activity or question to engage learners.\n- Main Activity (7–10 min): present and practice the topic using interactive methods.\n- Game (2–3 min): simple game to reinforce learning (Charades/Matching/Quiz).\n- Wrap-up (1–2 min): summarize and check understanding.\n- The class is conducted in full English and must be *recorded*\n\nPlease confirm your attendance by replying to this message. We look forward to meeting you😊`;const messages={'Offering Letter':`Hello *${name}*!\n\nYour offering letter has been sent to your email. Please submit the offering letter by uploading the Perjanjian Kerjasama letter, which can be downloaded from the offer letter email, and then submitting it through:\nhttps://pengajar.ruangguru.com/private-document\n\n> You can refer to the submission guide here:\n> https://tinyurl.com/panduansubmitoffer\n\nIf you have not yet received the offer letter email, you can access the following page:\nhttps://pengajar.ruangguru.com/teacher-rate\n\nOnce you have clicked *Accept*, please proceed with the following steps:\n> Download and sign the Non-Disclosure Agreement (Pages 5–7) from:\n> https://drive.google.com/file/d/1ZNpZ-d0APxjtsssckf6Ec01D8j8OWTrj/view?usp=sharing\n\n> Upload the signed Non-Disclosure Agreement through:\n> https://pengajar.ruangguru.com/private-document\n\n*Notes:*\n- For the Effective Date, please enter the date on which you sign the document.\n- For the Department section, please write the product name stated in your offering rate.\n\nPlease confirm once done. Thank you😊`,'Onboarding':`Hi *${name}*!\n\nJust a reminder to complete your onboarding via Akademia and our internal onboarding👩‍💻\n\nAlso please join the EA Teachers WhatsApp group using the link below:\nhttps://chat.whatsapp.com/IK1SdI5CgNJC2rZPKZdkho\n\nThank you!😊`,'Nego':`Hello, *${name}* 😊\n\nYour rate negotiation has been processed. Please check your Akademia account to see the updated rate🙌`,'Video Ajar':`Hi *${name}*!\n\nFor the next step, please upload the link of your *demo teaching video* to Akademia (https://pengajar.ruangguru.com/recruitment). This will be the last step of the hiring process😊\n\nThank you! 😊`,'Online Test':`Thank you so much for your confirmation😊\n\nFor the next step, please register first at https://pengajar.ruangguru.com/ruangguru and then complete the *Non-Dasher Online Test*.\n\nIf you’re already registered on Akademia, please complete the Online Test using this link: https://app.ruangguru.com/ruanguji/guru/2dec6f8b-236e-4a3a-9488-7a04ae2bdb83/EVENT_TYPE-MJVB934V/EVENT-N2UGV8GT\n\nKindly let me know once you’ve finished!🙌`,'Onsite Assessment':onsite,'Onsite Wave 6':onsite,'Approached':`Hello, *${name}*! My name is Agnes from English Academy Ruangguru 👋\n\nWe would like to invite you to join us as a part-time English teacher at our *${center}*.\nLocation: ${location}\nSchedule: Monday–Saturday (flexible hours)\n\nThis is a great opportunity to teach in person, gain valuable experience, and make a direct impact on our students' learning journey.\n\nWould you be interested?\nIf yes, I will share the next steps of the hiring process with you.\n\nWe look forward to hearing your positive response. Thank you!😊`,'Ready to Teach':`Hi *${name}*!\n\nWelcome to English Academy as the new Master Teacher at English Academy ${center}👋\n\nPlease join the EA Teachers WhatsApp group using the link below:\n> https://chat.whatsapp.com/IK1SdI5CgNJC2rZPKZdkho\n> https://chat.whatsapp.com/ENeZoXKvj5LDNToskRgaFG?s=cl&p=i&ilr=0\n\nThank you!😊`,'Pre-screening':`Thank you for your confirmation😊\n\nBefore we move forward, please fill out the form below and let me know once you're done. Thank you🙌\n\nhttps://forms.gle/hwtfe3nV3w7Z4kDz8`,'Approval HQ':`Selamat siang, kakak-kakak, mohon approval untuk kandidat MTC berikut:\n\n*${name}*\n*${center}*\n\n*Hasil tes*\n- Dasher:\n- Non-Dasher:\n- ⁠Pedagogical:\n- ⁠IELTS:\n- ⁠TOEFL:\n\n*Hasil observasi*\n- Q4 (MT Mitra):  (link)\n- ⁠Dengan sheet observasi MTC: (link)\n- ⁠Demo teaching & lesson plan: link\n\n*Notes:*`,'Rejected/Cancelled':`Hi *${name}*!\n\nThank you for your time and interest in joining us. Unfortunately, we will not move forward with your application for now, but we appreciate your effort and wish you the best in your teaching journey🙌`,'Interview':`Hi, we’ve received your Online Test result😊\n\nThe next step is interview and demo teaching session. The interview will be conducted online via Google Meet, while the demo teaching session will be conducted offline at the ${center} center.\n\nAre you available to do the online interview tomorrow at ?`,'Onboarding Regional':`Before you start your journey at English Academy *${center}*, I’d like to invite you to an onboarding session with me. This session will introduce you to your role as a Master Teacher, the English Academy teaching framework, and the administrative tasks you need to complete as a teacher.\n\nHere’s the link to the online onboarding session:\n\n\nPlease let me know if you’re unable to attend or if you have any other concerns. Thank you😊`,'Online Test New':`Thank you so much for your confirmation😊\n\nFor the next step, please proceed with the Non-Dasher Online Test using the link below:\n> https://app.ruangguru.com/ruanguji/guru/2dec6f8b-236e-4a3a-9488-7a04ae2bdb83/EVENT_TYPE-MJVB934V/EVENT-N2UGV8GT\n\nKindly let me know once you’ve finished!🙌`};return messages[step]||`Hi *${name}*, this is Agnes from English Academy Ruangguru. I would like to follow up about your application status.`}
function hiringWhatsAppUrl(row){const phone=hiringPhone(row.phone);return phone?`https://api.whatsapp.com/send?phone=${phone}&text=${encodeURIComponent(hiringMessage(row))}`:''}
async function postHiringUpdate(payload){const config=window.ACOPS_CONFIG||{},token=mppApiToken();if(!config.mppWriteApiUrl||!token){setMppSaveStatus('Saved locally · connect sheet to sync','local');return{ok:true,local:true}}setMppSaveStatus('Saving to Hiring EA…','saving');const response=await fetch(config.mppWriteApiUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({token,module:'hiring',...payload})}),result=await response.json();if(!result.ok)throw Error(result.error||'Hiring EA update failed');setMppSaveStatus('Saved to Hiring EA','synced');return result}
