async function initEvents(){syncEventsFilterElements();if(!document.getElementById('eventsYear')?.dataset.bound){const yearEl=document.getElementById('eventsYear');if(yearEl){yearEl.dataset.bound='true';yearEl.addEventListener('change',e=>{eventsState.year=e.target.value;renderEvents()})}const monthEl=document.getElementById('eventsMonth');if(monthEl){monthEl.dataset.bound='true';monthEl.addEventListener('change',e=>{eventsState.month=e.target.value;renderEvents()})}const searchEl=document.getElementById('eventsSearch');if(searchEl){searchEl.dataset.bound='true';searchEl.addEventListener('input',e=>{eventsState.search=e.target.value;renderEvents()})}const sortEl=document.getElementById('eventsSort');if(sortEl){sortEl.dataset.bound='true';sortEl.addEventListener('change',e=>{eventsState.sort=e.target.value;renderEvents()})}const exportBtn=document.getElementById('exportEvents');if(exportBtn){exportBtn.dataset.bound='true';exportBtn.addEventListener('click',exportEvents)}}const cached=loadEventsCache();if(cached&&cached.length){eventRows=cached;populateEventsYearDropdown();syncEventsFilterElements();renderEvents()}if(eventsLoading)return;eventsLoading=true;const root=document.getElementById('eventsTable');try{const fresh=await loadEventRecords(true);eventRows=fresh;eventsLoaded=true;saveEventsCache(fresh);populateEventsYearDropdown();syncEventsFilterElements();renderEvents();startEventsAutoRefresh()}catch(error){console.warn('Events data load issue',error);if(!eventRows.length&&root){root.innerHTML='<div class="empty-state"><strong>Couldn’t load Event data.</strong><br/><button onclick="eventsLoading=false;initEvents()" class="outline-button" style="margin-top:10px;">Retry Loading ↻</button></div>'}}finally{eventsLoading=false}}
